/* Generated by nexus-connect. Sends traces, metrics and logs to Nexus over OTLP/HTTP. Remove with: nexus-connect --undo
 * Settings come from OTEL_* environment variables, or from .env.nexus next to this file (never commit that file: it holds the token). */
import fs from 'node:fs';
import { register } from 'node:module';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { logs as apiLogs, metrics } from '@opentelemetry/api';
import { logs } from '@opentelemetry/api-logs';
import { OTLPLogExporter } from '@opentelemetry/exporter-logs-otlp-proto';
import { OTLPMetricExporter } from '@opentelemetry/exporter-metrics-otlp-proto';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-proto';
import { registerInstrumentations } from '@opentelemetry/instrumentation';
import { HttpInstrumentation } from '@opentelemetry/instrumentation-http';
import { resourceFromAttributes } from '@opentelemetry/resources';
import { BatchLogRecordProcessor, LoggerProvider } from '@opentelemetry/sdk-logs';
import { MeterProvider, PeriodicExportingMetricReader } from '@opentelemetry/sdk-metrics';
import { BatchSpanProcessor, NodeTracerProvider } from '@opentelemetry/sdk-trace-node';
/*__EXTRA_IMPORTS__*/

// Lets instrumentations patch ES-module apps when this file is loaded with `node --import ./nexus-telemetry.mjs` (a no-op otherwise).
try { register('@opentelemetry/instrumentation/hook.mjs', import.meta.url); } catch { /* old Node */ }
const here = path.dirname(fileURLToPath(import.meta.url));

// 1. load .env.nexus (never overrides variables that are already set)
try {
  for (const line of fs.readFileSync(path.join(here, '.env.nexus'), 'utf8').split(/\r?\n/)) {
    const m = /^\s*([A-Z0-9_]+)\s*=\s*(.*?)\s*$/.exec(line);
    if (m && !line.trim().startsWith('#') && process.env[m[1]] === undefined) process.env[m[1]] = m[2].replace(/^["']|["']$/g, '');
  }
} catch {
  /* no env file: rely on real environment variables */
}

// 2. service name: OTEL_SERVICE_NAME, else apps/<name> or services/<name> in the entry path, else package.json name, else folder
function serviceName() {
  if (process.env.OTEL_SERVICE_NAME) return process.env.OTEL_SERVICE_NAME;
  const entry = (process.argv[1] || '').replace(/\\/g, '/');
  const m = /\/(?:apps|services)\/([^/]+)\//.exec(entry);
  if (m) return m[1];
  try {
    const pkg = JSON.parse(fs.readFileSync(path.join(path.dirname(path.resolve(entry)), '..', 'package.json'), 'utf8'));
    if (pkg.name) return String(pkg.name).replace(/^@[^/]+\//, '');
  } catch {
    /* ignore */
  }
  return path.basename(process.cwd());
}

// With NODE_OPTIONS=--import, package-manager and tsx wrapper processes load this file too: they are not services.
function isToolingProcess() {
  const a = (process.argv[1] || '').split(String.fromCharCode(92)).join('/');
  return ['/npm/bin/', '/pnpm/bin/', '/node_modules/.bin/', '/tsx/dist/cli', '/npm-cli.js', '/npx-cli.js', '/corepack/'].some((p) => a.includes(p)) || /\/(npm|npx|pnpm|yarn|corepack)(\.c?js)?$/.test(a);
}

if (process.env.NEXUS_DISABLED !== '1' && process.env.OTEL_EXPORTER_OTLP_ENDPOINT && !globalThis.__nexusTelemetryStarted && !isToolingProcess()) {
  globalThis.__nexusTelemetryStarted = true;
  try {
    const name = serviceName();
    const resource = resourceFromAttributes({
      'service.name': name,
      'service.instance.id': `${os.hostname()}-${process.pid}`,
      'deployment.environment': process.env.NEXUS_ENV || 'development',
      'host.name': os.hostname(),
    });
    const tracerProvider = new NodeTracerProvider({ resource, spanProcessors: [new BatchSpanProcessor(new OTLPTraceExporter())] });
    tracerProvider.register();
    const meterProvider = new MeterProvider({ resource, readers: [new PeriodicExportingMetricReader({ exporter: new OTLPMetricExporter(), exportIntervalMillis: 15000 })] });
    metrics.setGlobalMeterProvider(meterProvider);
    const loggerProvider = new LoggerProvider({ resource, processors: [new BatchLogRecordProcessor({ exporter: new OTLPLogExporter() })] });
    logs.setGlobalLoggerProvider(loggerProvider);
    // @opentelemetry/api 1.10+ has its own logs registry (the pino instrumentation reads it): register both.
    if (apiLogs && apiLogs.setGlobalLoggerProvider) apiLogs.setGlobalLoggerProvider(loggerProvider);
    registerInstrumentations({ instrumentations: [new HttpInstrumentation()/*__EXTRA_INSTRUMENTATIONS__*/] });

    let closing = false;
    const flush = async () => {
      if (closing) return;
      closing = true;
      await Promise.allSettled([tracerProvider.shutdown(), meterProvider.shutdown(), loggerProvider.shutdown()]);
    };
    process.once('SIGTERM', () => { void flush(); });
    process.once('SIGINT', () => { void flush(); });
    process.once('beforeExit', () => { void flush(); });
    console.log(`[nexus] telemetry on: service=${name} endpoint=${process.env.OTEL_EXPORTER_OTLP_ENDPOINT}`);
  } catch (e) {
    // Telemetry must never stop the application from starting.
    console.warn('[nexus] telemetry NOT started:', e && e.message ? e.message : e);
  }
}
